// ===== Error clinic: the slips that cost marks in a real diagnostic, taught as habits =====
(function(){
const q=(q,a,w,e)=>{const o=sh([a,...w]);return{q,o,a:o.indexOf(a),e}};
COURSE.push({ id:"cl", t:"Error clinic: slips that cost marks", steps:[
 [1,"Most lost marks are not 'I can't do it'. They are <b>slips</b>: stopping one line early, mixing up radians and degrees, or one tiny arithmetic error. This lesson trains the habits that remove them. Each step shows a slip, then the fix.",null,["Is a slip the same as not understanding?","No. A slip is knowing the method but losing the mark. Slips are the cheapest marks to win back."],[]],
 [1,"<b>Finish the question.</b> Read the last line again before you stop. 'Find the points of intersection' needs <b>both coordinates</b>. Solve $x^2-3x=4x-10$: $x^2-7x+10=0$, so $x=2$ or $5$. Now put each back in a line: $y=4(2)-10=-2$ and $y=4(5)-10=10$. Answer: $(2,-2)$ and $(5,10)$.",null,["What must you do after finding x?","Substitute back to get y, then write the point as (x, y)."],["Stopping at the x-values. The question asked for points."]],
 [1,"<b>Right-angled triangles: label first.</b> $\\tan\\theta=\\frac{\\text{opposite}}{\\text{adjacent}}$. The hypotenuse is the longest side and is <b>never</b> in tan. In a 5-12-13 triangle with $\\theta$ opposite the 5: $\\tan\\theta=\\frac{5}{12}$, $\\sin\\theta=\\frac{5}{13}$, $\\cos\\theta=\\frac{12}{13}$.",null,["Which side is never used in tan?","The hypotenuse (longest side)."],["Putting 13 in tan. Write O, A, H on the sides before choosing a ratio."]],
 [1,"<b>Radians or degrees: match the question.</b> If the interval is $0\\le x\\le2\\pi$, answers are in radians. $\\cos x=0.5$ gives $x=\\frac{\\pi}{3}$ and $\\frac{5\\pi}{3}$ (not 60° and 300°). Check your calculator mode every time you open it. Exact values to know: $\\frac{\\pi}{6}=30^\\circ,\\ \\frac{\\pi}{4}=45^\\circ,\\ \\frac{\\pi}{3}=60^\\circ$.",null,["Interval 0 to 2π. What unit is the answer?","Radians."],["Giving degrees when the question is in radians, or leaving the calculator in the wrong mode."]],
 [1,"<b>Comparing fractions: use a common denominator, or convert to percent.</b> $\\frac14$ vs $\\frac{3}{10}$: $\\frac{5}{20}$ vs $\\frac{6}{20}$, so $\\frac{3}{10}$ is bigger. Or $25\\%$ vs $30\\%$. A bigger denominator does not mean a bigger fraction.",null,["Which is bigger, 2/5 or 3/8?","2/5 = 16/40, 3/8 = 15/40, so 2/5."],["Comparing the denominators only."]],
 [2,"<b>The chain rule with e.</b> $\\frac{d}{dx}e^{2x}=2e^{2x}$: the derivative of the power ($2$) multiplies the original. There is <b>no extra x</b>. Likewise $\\frac{d}{dx}e^{x^2}=2xe^{x^2}$ (the 2x comes from the power, not from a product).",null,["Differentiate e^(3x).","3e^(3x)."],["Writing 2x·e^(2x). The x only appears if the power's derivative contains x."]],
 [2,"<b>Counting without replacement.</b> The bag shrinks after each draw. 5 red and 3 blue: $P(\\text{both red})=\\frac58\\times\\frac47=\\frac{20}{56}=\\frac{5}{14}$. The second fraction has <b>one fewer red and one fewer total</b>. Draw a tree diagram when unsure.",null,["After drawing one red from 5 red + 3 blue, what is P(second red)?","4/7."],["Using the same denominator both times (that is with replacement)."]],
 [2,"<b>All solutions of a trig equation.</b> $\\sin x=-\\frac12$ on $0\\le x\\le2\\pi$: sine is negative in quadrants 3 and 4. Reference angle $\\frac\\pi6$, so $x=\\pi+\\frac\\pi6=\\frac{7\\pi}{6}$ and $x=2\\pi-\\frac\\pi6=\\frac{11\\pi}{6}$. Always sketch the quadrants (ASTC) and list <b>every</b> solution in range.",null,["How many solutions does sin x = −1/2 have in 0 to 2π?","Two: 7π/6 and 11π/6."],["Finding only one solution and stopping."]],
 [2,"<b>Complex numbers: use $i^2=-1$.</b> $(2+3i)(1-i)=2-2i+3i-3i^2$. Now replace $-3i^2$ by $+3$: $=2+3+i=5+i$. Expand with all four products, then swap every $i^2$ for $-1$.",null,["What is i²?","−1."],["Leaving $i^2$ in the answer, or forgetting to flip its sign."]],
 [2,"<b>Integrate a product: expand first, never integrate factors separately.</b> $\\int(x+1)(x+2)\\,dx=\\int(x^2+3x+2)\\,dx=\\frac{x^3}{3}+\\frac{3x^2}{2}+2x+c$. Integrating $(x+1)$ and $(x+2)$ separately and multiplying is always wrong.",null,["Is ∫fg = ∫f · ∫g?","No."],["Integrating each factor on its own and multiplying."]],
 [3,"<b>u-substitution, as a recipe.</b> $\\int2x(x^2+1)^3dx$. (1) Let $u=x^2+1$. (2) $du=2x\\,dx$. (3) Rewrite: $\\int u^3\\,du=\\frac{u^4}{4}+c$. (4) Put x back: $\\frac{(x^2+1)^4}{4}+c$. Choose u as the 'inside' whose derivative is (nearly) sitting next to it. Check by differentiating your answer.",null,["What do you do last?","Substitute x back in, then differentiate to check."],["Forgetting to replace u by x at the end, or forgetting the +c."]],
 [2,"<b>Initial conditions: use them to find the constant.</b> $\\frac{dy}{dx}=2x$ gives $y=x^2+c$. If $y=2$ when $x=0$ then $c=2$, so $y=x^2+2$ and $y(1)=3$. Read which variable the given value belongs to, and do not mix the point's x and y.",null,["y=x²+c and y(0)=2. What is c?","2."],["Putting the y-value in as if it were x, or skipping the constant."]],
 [1,"<b>Arithmetic: slow down on signs.</b> $b^2-4ac$ with $a=-2,b=-3,c=1$: $(-3)^2=9$, and $-4(-2)(1)=+8$, so $9+8=17$. Put brackets round every negative, do one operation per line, then <b>re-check each answer by substituting back</b>. Never guess: if stuck, write what you do know, mark the question, and return to it.",null,["Why use brackets for negatives?","So the sign is squared or multiplied correctly."],["Dropping a minus sign, or writing $-3^2$ when you mean $(-3)^2$."]]
 ], qs:[
 q("The curves $y=x^2-3x$ and $y=4x-10$ intersect at:","$(2,-2)$ and $(5,10)$",["$x=2$ and $x=5$","$(-2,2)$ and $(10,5)$","$(2,-2)$ only"],"Solve for x, then substitute back to get y."),
 q("A right triangle has sides 5, 12, 13 and $\\theta$ is opposite the 5. $\\tan\\theta=$","$\\frac{5}{12}$",["$\\frac{13}{12}$","$\\frac{5}{13}$","$\\frac{12}{5}$"],"tan = opposite/adjacent; 13 is the hypotenuse."),
 q("Solve $\\cos x=0.5$ for $0\\le x\\le2\\pi$:","$\\frac\\pi3$ and $\\frac{5\\pi}{3}$",["$60^\\circ$ and $300^\\circ$","$\\frac\\pi3$ only","$\\frac{2\\pi}{3}$ and $\\frac{4\\pi}{3}$"],"The interval is in radians, and cosine is positive in quadrants 1 and 4."),
 q("Which is larger?","$\\frac{3}{10}$",["$\\frac14$","They are equal","Cannot tell"],"5/20 vs 6/20, or 25% vs 30%."),
 q("$\\frac{d}{dx}e^{2x}=$","$2e^{2x}$",["$2xe^{2x}$","$e^{2x}$","$2e^{2x-1}$"],"Chain rule: multiply by the derivative of 2x, which is 2."),
 q("A bag has 5 red and 3 blue marbles. Two are drawn without replacement. $P(\\text{both red})=$","$\\frac{5}{14}$",["$\\frac{25}{64}$","$\\frac{25}{56}$","$\\frac{5}{16}$"],"5/8 × 4/7 = 20/56 = 5/14."),
 q("Solve $\\sin x=-\\frac12$ for $0\\le x\\le2\\pi$:","$\\frac{7\\pi}{6}$ and $\\frac{11\\pi}{6}$",["$\\frac{7\\pi}{6}$ only","$\\frac\\pi6$ and $\\frac{5\\pi}{6}$","$\\frac{5\\pi}{6}$ and $\\frac{7\\pi}{6}$"],"Sine is negative in quadrants 3 and 4."),
 q("$(2+3i)(1-i)=$","$5+i$",["$-1+i$","$5-i$","$2-3i$"],"2 − 2i + 3i − 3i², and −3i² = +3."),
 q("$\\int(x+1)(x+2)\\,dx=$","$\\frac{x^3}{3}+\\frac{3x^2}{2}+2x+c$",["$\\left(\\frac{x^2}{2}+x\\right)\\left(\\frac{x^2}{2}+2x\\right)+c$","$x^3+3x^2+2x+c$","$\\frac{x^3}{3}+\\frac{3x^2}{2}+2+c$"],"Expand to x² + 3x + 2 first."),
 q("$\\int2x(x^2+1)^3\\,dx=$","$\\frac{(x^2+1)^4}{4}+c$",["$(x^2+1)^4+c$","$\\frac{(x^2+1)^4}{8}+c$","$\\frac{2x(x^2+1)^4}{4}+c$"],"u = x²+1, du = 2x dx, so ∫u³ du."),
 q("$\\frac{dy}{dx}=2x$ and $y=2$ when $x=0$. Then $y(1)=$","$3$",["$1$","$2$","$5$"],"y = x² + c with c = 2."),
 q("Evaluate $b^2-4ac$ for $a=-2,\\ b=-3,\\ c=1$:","$17$",["$1$","$-7$","$9$"],"9 − 4(−2)(1) = 9 + 8.")
 ]});
MODS.push({ t:"Your error clinic · quick wins", ids:["cl"], intro:"Short drills on the slips that cost marks in the starting-point test: unfinished answers, radians vs degrees, signs, chain rule with e, counting and u-substitution. Do this first: it is the quickest improvement available." });
})();

