COURSE.forEach(c => { c.base = c.base || c.qs.slice(); regen(c); });

// ===== Mistakes shown inside the steps they belong to; stretch steps for the foundation lessons =====
COURSE.find(c => c.id === "f1").steps.push([3, "<b>Stretch: why $a^0=1$, and where the quadratic formula comes from.</b> $\\frac{a^3}{a^3}=a^{3-3}=a^0$, and anything divided by itself is 1, so $a^0=1$. The quadratic formula comes from completing the square on $ax^2+bx+c=0$: divide by $a$, write $\\left(x+\\frac{b}{2a}\\right)^2=\\frac{b^2-4ac}{4a^2}$, then take square roots. The part under the root, $b^2-4ac$, decides how many solutions exist."]);
COURSE.find(c => c.id === "f2").steps.push([3, "<b>Stretch.</b> Why do perpendicular gradients multiply to $-1$? Turn a line with rise $m$ and run 1 through $90^\\circ$: the rise and run swap and one changes sign, giving gradient $-\\frac1m$. And trig ratios depend only on the angle, not the size of the triangle (similar triangles), which is why $\\sin$, $\\cos$, $\\tan$ are well defined and why a unit circle (radius 1) works."]);
COURSE.find(c => c.id === "f3").steps.push([3, "<b>Stretch.</b> $F=ma$ is really 'force is the rate of change of momentum', $F=\\frac{\\Delta(mv)}{\\Delta t}$, which also covers cases where mass changes (rockets). And $E_k=\\frac12mv^2$ comes from work: a constant force $F=ma$ over distance $s$, with $v^2=2as$, gives $W=Fs=m\\cdot\\frac{v^2}{2}$."]);
(function () {
  const stop = new Set(["that","this","with","from","have","when","then","than","your","they","them","will","what","into","only","does","just","also","both","each","same","more","most","many","some","such","like","dont","not","the","and","for","are","but","use","you","can"]);
  const tok = h => (String(h).replace(/<[^>]+>/g, " ").replace(/\\([a-zA-Z]+)/g, " $1 ").toLowerCase().match(/[a-z0-9]{3,}/g) || []).filter(w => !stop.has(w));
  COURSE.forEach(c => {
    const t = OT[c.id]; if (!t) return;
    c.steps = c.steps.filter(s => !String(s[1]).startsWith("<b>🔍"));
    const items = t.split("<br>").slice(1).map(x => x.replace(/^\s*(<b>\d+\.<\/b>|•)\s*/, "").trim()).filter(x => x.length > 12);
    const bags = c.steps.map(s => new Set(tok(s[1])));
    c.steps.forEach(s => { s[4] = []; });
    items.forEach(it => {
      const w = tok(it); let best = -1, bs = -1;
      bags.forEach((b, i) => { const st = String(c.steps[i][1]); if (st.startsWith("<b>✍️") || st.startsWith("<b>🌉")) return; const sc = w.filter(x => b.has(x)).length / (Math.sqrt(b.size) || 1); if (sc > bs) { bs = sc; best = i; } });
      if (best < 0) best = 0; c.steps[best][4].push(it);
    });
  });
})();
